# Expected values generated by test/scipy/gen_optimize_expected.py (scipy 1.18.1).
import numpy as np
import scipy.optimize as so
from scipy import optimize

def close(x, ref, rtol: float = 1e-7, atol: float = 1e-10) -> bool:
    a = np.asarray(x, float)
    r = np.asarray(ref, float)
    if a.size != r.size:
        print('size', a.size, r.size)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def check(cond: bool, what: str):
    if not cond:
        print('TEST FAILED:', what)

def f1(x):
    return (x - 2.0) * x * (x + 2.0) ** 2

def g(x):
    return x ** 3 - 2 * x - 5

def gp(x):
    return 3 * x ** 2 - 2

def gpp(x):
    return 6 * x

def F(x):
    return np.array([x[0] + 0.5 * (x[0] - x[1]) ** 3 - 1.0, 0.5 * (x[1] - x[0]) ** 3 + x[1]])

def res(x):
    return np.array([10 * (x[1] - x[0] ** 2), (1 - x[0])])

def quad(x, a):
    return float(np.sum((x - a) ** 2)) + 0.5 * x[0] * x[1]

def model(x, a, b, c):
    return a * np.exp(-b * x) + c

X0 = np.array([1.3, 0.7, 0.8, 1.9, 1.2])

def test_minimize():
    CASES = [
        ('Nelder-Mead', [0.9991011512589454, 0.9982092322872904, 0.9964634595940463, 0.9929755505492563, 0.98600385279128], 6.617481708884532e-05, 141, 243, 0),
        ('BFGS', [0.9999992455592365, 0.9999985167568398, 0.9999970646373476, 0.9999941558218923, 0.9999883334987006], 4.5820591227178514e-11, 25, 180, 30),
        ('CG', [0.9999991590085519, 0.9999983129757244, 0.9999966212468174, 0.9999932271411539, 0.9999864250667241], 6.095489404812926e-11, 67, 834, 139),
        ('Powell', [1.000000000000173, 1.0000000000003153, 1.000000000001097, 1.0000000000009888, 1.000000000002034], 1.6967633615782998e-22, 18, 988, 0),
        ('L-BFGS-B', [0.9999995691908724, 0.9999991461596862, 0.9999983361026876, 0.9999966688146695, 0.9999933624886974], 1.5040625768099434e-11, 24, 156, 26),
    ]
    for m, x, fun, nit, nfev, njev in CASES:
        r = so.minimize(so.rosen, X0, method=m)
        check(close(r.x, x, 1e-5), m + ' x')
        check(abs(r.fun - fun) < 1e-9, m + ' fun')
        check(r.success, m + ' success')
        # iteration counts can differ by a step in debug (non-FMA) builds
        check(abs(r.nit - nit) <= 3, m + ' nit')
        check(abs(r.nfev - nfev) <= 40, m + ' nfev')
    r = so.minimize(so.rosen, X0, jac=so.rosen_der)
    check(close(r.x, [1.0000000427014981, 1.0000000998410783, 1.0000002142328246, 1.0000004431752, 1.0000009152577316], 1e-6), 'bfgs jac x')
    check(r.nit == 25 and r.nfev == 30 and r.njev == 30, 'bfgs jac counts')
    check(r.message == 'Optimization terminated successfully.', 'bfgs msg')
    check(r.hess_inv.shape[0] == 5, 'bfgs hess_inv')
    r = so.minimize(so.rosen, X0, method='CG', jac=so.rosen_der)
    check(close(r.x, [0.9999997721875559, 0.9999995413903922, 0.9999990921544192, 0.9999981911446544, 0.9999963620011588], 1e-6), 'cg jac x')
    check(r.nit == 47 and r.nfev == 97 and r.njev == 97, 'cg jac counts')
    r = so.minimize(so.rosen, X0, method='L-BFGS-B', jac=so.rosen_der)
    check(close(r.x, [1.0000001063151185, 1.0000002130794126, 1.0000004591484999, 1.0000009075913048, 1.0000018449804888], 1e-6), 'lbfgsb jac x')
    check(r.nit == 24 and r.nfev == 26 and r.njev == 26, 'lbfgsb jac counts')
    a = np.array([1.0, -2.0])
    r = so.minimize(quad, np.zeros(2), args=(a,), tol=1e-10)
    check(close(r.x, [1.6, -2.4], 1e-7), 'quad args x')
    check(abs(r.fun + 1.4) < 1e-12, 'quad args fun')
    r = optimize.minimize(quad, [0.0, 0.0], args=(a,), method='nelder-mead')
    check(close(r.x, [1.6, -2.4], 0.0, 1e-3), 'nm list x0')

def test_minimize_bounds():
    r = so.minimize(so.rosen, np.array([3.0, 3.0]), method='L-BFGS-B', bounds=[(-1.0, 2.0), (0.5, 1.5)])
    check(close(r.x, [-0.6984564154148524, 0.5], 1e-6), 'lbb x')
    check(abs(r.fun - 2.8995374374324947) < 1e-9, 'lbb fun')
    check(r.nit == 10 and r.nfev == 45, 'lbb counts')
    check(r.message == 'CONVERGENCE: NORM OF PROJECTED GRADIENT <= PGTOL', 'lbb msg')
    r = so.minimize(so.rosen, np.array([3.0, 3.0]), bounds=((None, 2.0), (0.5, None)))
    check(close(r.x, [0.999995509449045, 0.999990941430417], 1e-5), 'lbb2 x')
    check(abs(r.nit - 24) <= 2, 'lbb2 nit')
    r = so.minimize(so.rosen, np.array([3.0, 3.0]), bounds=so.Bounds([-1.0, 0.5], [2.0, 1.5]))
    check(close(r.x, [-0.6984564154148524, 0.5], 1e-6), 'Bounds obj')
    r = so.minimize(so.rosen, np.array([1.5, 1.5]), method='Nelder-Mead', bounds=[(-1.0, 2.0), (0.5, 1.5)])
    check(close(r.x, [1.000021070463667, 1.000043484402083], 1e-7), 'nmb x')
    check(r.nit == 72 and r.nfev == 139, 'nmb counts')
    r = so.minimize(so.rosen, np.array([1.5, 1.5]), method='Powell', bounds=[(-1.0, 2.0), (0.5, 1.5)])
    check(close(r.x, [0.999996339974864, 0.9999929972406396], 1e-6), 'pwb x')
    check(abs(r.nit - 10) <= 1, 'pwb nit')

def test_minimize_options():
    r = so.minimize(so.rosen, X0, method='Nelder-Mead', options={'maxiter': 50})
    check(close(r.x, [1.0482002076557548, 0.9197590797901491, 1.0094552024975, 1.015240319649525, 1.1163441865047314], 1e-9), 'nm maxiter x')
    check(r.nit == 50 and r.nfev == 86 and r.status == 2 and not r.success, 'nm maxiter status')
    check(r.message == 'Maximum number of iterations has been exceeded.', 'nm maxiter msg')
    r = so.minimize(so.rosen, X0, method='Nelder-Mead', options={'adaptive': 1.0, 'xatol': 1e-8, 'fatol': 1e-8})
    check(abs(r.fun - 2.890749886613622e-17) < 1e-15, 'nm adaptive fun')
    check(r.nit == 487 and r.nfev == 838, 'nm adaptive counts')
    r = so.minimize(so.rosen, X0, method='BFGS', options={'gtol': 1e-8, 'maxiter': 10.0})
    check(abs(r.fun - 0.07967039517214744) < 1e-7, 'bfgs maxiter fun')
    check(r.nit == 10 and r.status == 1 and not r.success, 'bfgs maxiter status')
    try:
        so.minimize(so.rosen, X0, method='foo')
        check(False, 'unknown method')
    except ValueError:
        pass
    try:
        so.minimize(so.rosen, np.array([1.0, 1.0]), method='L-BFGS-B', bounds=[(2.0, 1.0), (0.0, 1.0)])
        check(False, 'bad bounds')
    except ValueError:
        pass

def test_scalar():
    r = so.minimize_scalar(f1)
    check(close(r.x, 1.2807764040333458, 1e-12) and close(r.fun, -9.914949590828147, 1e-14), 'brent')
    check(r.nit == 11 and r.nfev == 14 and r.success, 'brent counts')
    r = so.minimize_scalar(f1, bracket=(0, 1, 2))
    check(close(r.x, 1.2807764138471118, 1e-12) and r.nit == 10 and r.nfev == 13, 'brent3')
    r = so.minimize_scalar(f1, bounds=(-3, -1), method='bounded')
    check(close(r.x, -2.000000202597239, 1e-12) and r.nfev == 12 and r.status == 0, 'bounded')
    r = so.minimize_scalar(f1, method='golden')
    check(close(r.x, 1.280776401465682, 1e-12) and r.nit == 38 and r.nfev == 43, 'golden')
    try:
        so.minimize_scalar(f1, bracket=(-1, 0, 2))
        check(False, 'bad bracket')
    except ValueError:
        pass
    try:
        so.minimize_scalar(f1, bounds=(0, 1), method='brent')
        check(False, 'bounds with brent')
    except ValueError:
        pass
    try:
        so.minimize_scalar(f1, bounds=(1, 0), method='bounded')
        check(False, 'reversed bounds')
    except ValueError:
        pass
    check(close(so.fminbound(f1, -3, -1), -2.000000202597239, 1e-12), 'fminbound')

def test_roots():
    check(close(so.brentq(g, 2, 3), 2.094551481542327, 1e-15), 'brentq')
    check(close(so.brenth(g, 2, 3), 2.0945514815423265, 1e-15), 'brenth')
    check(close(so.bisect(g, 2, 3), 2.0945514815412025, 1e-15), 'bisect')
    check(close(so.ridder(g, 2, 3), 2.094551481543327, 1e-15), 'ridder')
    check(close(so.brentq(lambda x, c: x * x - c, 0, 3, args=(2.0,)), 1.4142135623730951, 1e-15), 'brentq args')
    r, info = so.brentq(g, 2, 3, full_output=True)
    check(info.converged and info.iterations == 7 and info.function_calls == 8, 'brentq full_output')
    try:
        so.brentq(g, 3, 4)
        check(False, 'same sign')
    except ValueError:
        pass
    try:
        so.brentq(g, 2, 3, xtol=-1.0)
        check(False, 'bad xtol')
    except ValueError:
        pass
    check(close(so.newton(g, 2.0), 2.0945514815423265, 1e-14), 'secant')
    check(close(so.newton(g, 2.0, fprime=gp), 2.0945514815423265, 1e-15), 'newton')
    check(close(so.newton(g, 2.0, fprime=gp, fprime2=gpp), 2.0945514815423265, 1e-15), 'halley')
    v = so.newton(lambda x: x * x - np.array([2.0, 3.0]), np.array([1.0, 1.0]), fprime=lambda x: 2 * x)
    check(close(v, [1.4142135623730951, 1.7320508075688772], 1e-12), 'array newton')
    s = so.root_scalar(g, bracket=[2.0, 3.0])
    check(close(s.root, 2.094551481542327, 1e-15) and s.iterations == 7 and s.function_calls == 8 and s.method == 'brentq', 'rs brentq')
    s = so.root_scalar(g, x0=2.0, fprime=gp)
    check(close(s.root, 2.0945514815423265, 1e-15) and s.iterations == 4 and s.function_calls == 8, 'rs newton')
    s = so.root_scalar(g, x0=2.0, x1=3.0)
    check(close(s.root, 2.094551481542327, 1e-14) and s.iterations == 6 and s.function_calls == 7, 'rs secant')
    s = so.root_scalar(g, method='bisect', bracket=[2.0, 3.0], xtol=1e-6)
    check(close(s.root, 2.0945520401000977, 1e-15) and s.iterations == 20 and s.function_calls == 22, 'rs bisect')
    s = so.root_scalar(g, x0=2.0, fprime=gp, fprime2=gpp)
    check(close(s.root, 2.0945514815423265, 1e-15) and s.method == 'halley', 'rs halley')
    try:
        so.root_scalar(g)
        check(False, 'no method')
    except ValueError:
        pass

def test_systems():
    check(close(so.fsolve(F, [0.0, 0.0]), [0.8411639019140096, 0.1588360980859903], 1e-12), 'fsolve')
    r = so.root(F, [0.0, 0.0])
    check(close(r.x, [0.8411639019140096, 0.1588360980859903], 1e-12), 'root x')
    check(r.nfev == 14 and r.status == 1 and r.success, 'root counts')
    check(r.message == 'The solution converged.', 'root msg')
    J = lambda x: np.array([[1 + 1.5 * (x[0] - x[1]) ** 2, -1.5 * (x[0] - x[1]) ** 2],
                            [-1.5 * (x[1] - x[0]) ** 2, 1 + 1.5 * (x[1] - x[0]) ** 2]])
    r = so.root(F, [0.0, 0.0], jac=J)
    check(close(r.x, [0.8411639019140096, 0.1588360980859903], 1e-10) and r.success, 'root jac')
    r = so.root(F, [0.0, 0.0], method='lm')
    check(close(r.x, [0.7252038049458908, 1.1102230246251565e-16], 1e-9, 1e-14), 'root lm')
    check(r.status == 1 and r.success and r.nfev == 21, 'root lm counts')

def test_least_squares():
    ls = so.least_squares(res, np.array([2.0, 2.0]))
    check(close(ls.x, [1.0, 1.0], 1e-12) and ls.cost < 1e-25, 'trf x')
    check(ls.nfev == 3 and ls.njev == 3 and ls.status == 1 and ls.success, 'trf counts')
    ls = so.least_squares(res, np.array([2.0, 2.0]), method='lm')
    check(close(ls.x, [1.0, 1.0], 1e-12) and ls.nfev == 4 and ls.status == 3, 'lm')
    ls = so.least_squares(res, np.array([2.0, 2.0]), bounds=([-np.inf, 1.5], np.inf))
    check(close(ls.x, [1.2243707490044007, 1.500000000000023], 1e-9), 'trfb x')
    check(close(ls.cost, 0.025213093946805685, 1e-9) and ls.nfev == 9 and ls.status == 2, 'trfb cost')
    check(ls.active_mask.tolist() == [0, -1], 'trfb active')
    jr = lambda x: np.array([[-20.0 * x[0], 10.0], [-1.0, 0.0]])
    ls = so.least_squares(res, np.array([2.0, 2.0]), jac=jr)
    check(close(ls.x, [1.0, 1.0], 1e-12), 'trf jac')
    try:
        so.least_squares(res, np.array([2.0, 2.0]), method='lm', bounds=(0.0, 3.0))
        check(False, 'lm bounds')
    except ValueError:
        pass
    try:
        so.least_squares(res, np.array([5.0, 2.0]), bounds=(0.0, 3.0))
        check(False, 'x0 infeasible')
    except ValueError:
        pass

def test_curve_fit():
    xd = np.linspace(0, 4, 50)
    yd = 2.5 * np.exp(-1.3 * xd) + 0.5 + 0.01 * np.sin(7 * xd)
    popt, pcov = so.curve_fit(model, xd, yd)
    check(close(popt, [2.5047129965613957, 1.3054712830665456, 0.5016760550914318], 1e-8), 'cf popt')
    check(close(pcov, [[1.7663918534940464e-05, 7.281839010062704e-06, -9.424987141421196e-07], [7.281839010062704e-06, 2.25789608190687e-05, 6.427662790954412e-06], [-9.424987141421196e-07, 6.427662790954412e-06, 3.425488608893417e-06]], 1e-6, 1e-15), 'cf pcov')
    popt, pcov = so.curve_fit(model, xd, yd, p0=[2.0, 1.0, 0.0], sigma=np.full(50, 0.1), absolute_sigma=True)
    check(close(popt, [2.504712996645821, 1.3054712831864832, 0.5016760551170746], 1e-8), 'cf sigma popt')
    check(close(pcov, [[0.0035257894449587644, 0.0014534842410033908, -0.00018812662103316721], [0.0014534842410033908, 0.004506852034053871, 0.001282987841915033], [-0.00018812662103316721, 0.001282987841915033, 0.0006837416209980878]], 1e-6), 'cf sigma pcov')
    popt, pcov = so.curve_fit(model, xd, yd, bounds=(0.0, [3., 1., 0.5]))
    check(close(popt, [2.410297358957038, 0.9999999999999999, 0.3902540992530585], 1e-6), 'cfb popt')
    check(close(pcov, [[0.0015346631833435594, 0.0002967178880024077, -0.00022534477867001466], [0.00029671788800240766, 0.0017296860027403633, 0.0008559100031457446], [-0.00022534477867001466, 0.0008559100031457444, 0.0006204806546956618]], 1e-4), 'cfb pcov')
    try:
        so.curve_fit(model, xd, yd, method='lm', bounds=(0.0, 1.0))
        check(False, 'cf lm bounds')
    except ValueError:
        pass

def test_lsap_numdiff():
    C = np.array([[4., 1., 3.], [2., 0., 5.], [3., 2., 2.]])
    r, c = so.linear_sum_assignment(C)
    check(r.tolist() == [0, 1, 2] and c.tolist() == [1, 0, 2], 'lsap')
    r, c = so.linear_sum_assignment(np.array([[4., 1., 3., 9.], [2., 0., 5., 1.]]).T, maximize=True)
    check(r.tolist() == [2, 3] and c.tolist() == [1, 0], 'lsap max')
    C2 = np.array([[0.6369616873214543, 0.2697867137638703, 0.04097352393619469, 0.016527635528529094, 0.8132702392002724, 0.9127555772777217, 0.6066357757671799, 0.7294965609839984], [0.5436249914654229, 0.9350724237877682, 0.8158535541215322, 0.002738500170148095, 0.8574042765875693, 0.033585575305464355, 0.7296554464299441, 0.17565562060255901], [0.8631789223498866, 0.5414612202490917, 0.2997118905373848, 0.42268722119765845, 0.028319671145462966, 0.12428327649956394, 0.6706244146936303, 0.6471895115742501], [0.6153851114812539, 0.38367755426188344, 0.997209935789211, 0.9808353387762301, 0.6855419844806947, 0.6504592762678163, 0.6884467305709401, 0.3889214239791038], [0.13509650502241122, 0.7214883401940817, 0.5253543224757259, 0.31024187555895566, 0.4858353588317891, 0.8894878343490003, 0.9340435159562497, 0.35779519670907023], [0.5715298307297609, 0.32186939107594215, 0.5943000301996968, 0.33791122550713326, 0.39161900052816123, 0.8902743520047923, 0.22715759353337972, 0.6231871446860424]])
    r, c = so.linear_sum_assignment(C2)
    check(r.tolist() == [0, 1, 2, 3, 4, 5] and c.tolist() == [2, 3, 4, 1, 0, 6], 'lsap rect')
    check(close(float(C2[r, c].sum()), 0.8179633480694801, 1e-14), 'lsap rect cost')
    r, c = so.linear_sum_assignment(np.zeros((0, 3)))
    check(r.size == 0 and c.size == 0, 'lsap empty')
    try:
        so.linear_sum_assignment(np.array([[1.0, np.nan], [2.0, 3.0]]))
        check(False, 'lsap nan')
    except ValueError:
        pass
    x = np.array([1.5, 1.9])
    check(close(so.approx_fprime(x, so.rosen), [211.00001335144043, -69.99999856948853], 1e-12), 'approx_fprime')
    check(close(so.check_grad(so.rosen, so.rosen_der, x), 1.34278562380321e-05, 1e-6), 'check_grad')
    check(close(so.rosen_der(x), [211.0, -70.0], 1e-14), 'rosen_der')

test_minimize()
test_minimize_bounds()
test_minimize_options()
test_scalar()
test_roots()
test_systems()
test_least_squares()
test_curve_fit()
test_lsap_numdiff()
print('done')
